import{_ as p,a0 as o,w as l,s as r,ao as d,I as i,x as a,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Debian 10 中配置 Chroot 環境的 SFTP 服務 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Debian 10 中配置 Chroot 環境的 SFTP 服務 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Debian 10 中配置 Chroot 環境的 SFTP 服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Debian 10 中配置 Chroot 環境的 SFTP 服務 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20190915 How to Configure SFTP Server with Chroot in Debian 10","title":"如何在 Debian 10 中配置 Chroot 環境的 SFTP 服務","tag":"202005","desc":""},"relativePath":"202005/20190915 How to Configure SFTP Server with Chroot in Debian 10.md","filePath":"[post].md"}'),c={name:"202005/20190915 How to Configure SFTP Server with Chroot in Debian 10.md"};function h(g,s,u,f,b,k){const e=o("Link");return l(),r("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-debian-10-中配置-chroot-環境的-sftp-服務" tabindex="-1">如何在 Debian 10 中配置 Chroot 環境的 SFTP 服務 <a class="header-anchor" href="#如何在-debian-10-中配置-chroot-環境的-sftp-服務" aria-label="Permalink to “如何在 Debian 10 中配置 Chroot 環境的 SFTP 服務”">​</a></h1><p>SFTP 意思是“<ruby>安全文件傳輸協議<rt>Secure File Transfer Protocol</rt></ruby>” 或 “<ruby>SSH 文件傳輸協議<rt>SSH File Transfer Protocol</rt></ruby>”，它是最常用的用於通過 <code>ssh</code> 將文件從本地系統安全地傳輸到遠程服務器的方法，反之亦然。<code>sftp</code> 的主要優點是，除 <code>openssh-server</code> 之外，我們不需要安裝任何額外的軟件包，在大多數的 Linux 發行版中，<code>openssh-server</code> 軟件包是默認安裝的一部分。<code>sftp</code> 的另外一個好處是，我們可以允許用户使用 <code>sftp</code> ，而不允許使用 <code>ssh</code> 。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202005/05/223518ip4mbdi4nggbdtgu.jpg" alt=""></p><p>當前發佈的 Debian 10 代號為 ‘Buster’，在這篇文章中，我們將演示如何在 Debian 10 系統中在 “監獄式的” Chroot 環境中配置 <code>sftp</code>。在這裏，Chroot 監獄式環境意味着，用户不能超出各自的家目錄，或者用户不能從各自的家目錄更改目錄。下面實驗的詳細情況：</p><ul><li>OS = Debian 10</li><li>IP 地址 = 192.168.56.151</li></ul><p>讓我們跳轉到 SFTP 配置步驟，</p><h3 id="步驟-1、使用-groupadd-命令給-sftp-創建一個組" tabindex="-1">步驟 1、使用 groupadd 命令給 sftp 創建一個組 <a class="header-anchor" href="#步驟-1、使用-groupadd-命令給-sftp-創建一個組" aria-label="Permalink to “步驟 1、使用 groupadd 命令給 sftp 創建一個組”">​</a></h3><p>打開終端，使用下面的 <code>groupadd</code> 命令創建一個名為的 <code>sftp_users</code> 組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# groupadd sftp_users</span></span></code></pre></div><h3 id="步驟-2、添加用户到組-sftp-users-並設置權限" tabindex="-1">步驟 2、添加用户到組 sftp_users 並設置權限 <a class="header-anchor" href="#步驟-2、添加用户到組-sftp-users-並設置權限" aria-label="Permalink to “步驟 2、添加用户到組 sftp_users 並設置權限”">​</a></h3><p>假設你想創建新的用户，並且想添加該用户到 <code>sftp_users</code> 組中，那麼運行下面的命令，</p><p><strong>語法：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#  useradd -m -G sftp_users &lt;用户名&gt;</span></span></code></pre></div><p>讓我們假設用户名是 <code>jonathan</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# useradd -m -G sftp_users jonathan</span></span></code></pre></div><p>使用下面的 <code>chpasswd</code> 命令設置密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# echo &quot;jonathan:&lt;輸入密碼&gt;&quot; | chpasswd</span></span></code></pre></div><p>假設你想添加現有的用户到 <code>sftp_users</code> 組中，那麼運行下面的 <code>usermod</code> 命令，讓我們假設已經存在的用户名稱是 <code>chris</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# usermod -G sftp_users chris</span></span></code></pre></div><p>現在設置用户所需的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# chown root /home/jonathan /home/chris/</span></span></code></pre></div><p>在各用户的家目錄中都創建一個上傳目錄，並設置正確地所有權：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# mkdir /home/jonathan/upload</span></span>
<span class="line"><span>root@linuxtechi:~# mkdir /home/chris/upload</span></span>
<span class="line"><span>root@linuxtechi:~# chown jonathan /home/jonathan/upload</span></span>
<span class="line"><span>root@linuxtechi:~# chown chris /home/chris/upload</span></span></code></pre></div><p><strong>注意:</strong> 像 Jonathan 和 Chris 之類的用户可以從他們的本地系統上傳文件和目錄。</p><h3 id="步驟-3、編輯-sftp-配置文件-etc-ssh-sshd-config" tabindex="-1">步驟 3、編輯 sftp 配置文件 /etc/ssh/sshd_config <a class="header-anchor" href="#步驟-3、編輯-sftp-配置文件-etc-ssh-sshd-config" aria-label="Permalink to “步驟 3、編輯 sftp 配置文件 /etc/ssh/sshd_config”">​</a></h3><p>正如我們已經陳述的，<code>sftp</code> 操作是通過 <code>ssh</code> 完成的，所以它的配置文件是 <code>/etc/ssh/sshd_config</code>，在做任何更改前，我建議首先備份文件，然後再編輯該文件，接下來添加下面的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# cp /etc/ssh/sshd_config /etc/ssh/sshd_config-org</span></span>
<span class="line"><span>root@linuxtechi:~# vim /etc/ssh/sshd_config</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>#Subsystem      sftp    /usr/lib/openssh/sftp-server</span></span>
<span class="line"><span>Subsystem       sftp    internal-sftp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Match Group sftp_users</span></span>
<span class="line"><span>  X11Forwarding no</span></span>
<span class="line"><span>  AllowTcpForwarding no</span></span>
<span class="line"><span>  ChrootDirectory %h</span></span>
<span class="line"><span>  ForceCommand internal-sftp</span></span>
<span class="line"><span>......</span></span></code></pre></div><p>保存並退出文件。</p><p>為使上述更改生效，使用下面的 <code>systemctl</code> 命令來重新啓動 <code>ssh</code> 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# systemctl restart sshd</span></span></code></pre></div><p>在上面的 <code>sshd_config</code> 文件中，我們已經註釋掉了以 <code>Subsystem</code> 開頭的行，並添加了新的條目 <code>Subsystem sftp internal-sftp</code> 和新的行。而</p><p><code>Match Group sftp_users</code> –&gt; 它意味着如果用户是 <code>sftp_users</code> 組中的一員，那麼將應用下面提到的規則到這個條目。</p><p><code>ChrootDierctory %h</code> –&gt; 它意味着用户只能在他們自己各自的家目錄中更改目錄，而不能超出他們各自的家目錄。或者換句話説，我們可以説用户是不允許更改目錄的。他們將在他們的目錄中獲得監獄一樣的環境，並且不能訪問其他用户的目錄和系統的目錄。</p><p><code>ForceCommand internal-sftp</code> –&gt; 它意味着用户僅被限制到只能使用 <code>sftp</code> 命令。</p><h3 id="步驟-4、測試和驗證-sftp" tabindex="-1">步驟 4、測試和驗證 sftp <a class="header-anchor" href="#步驟-4、測試和驗證-sftp" aria-label="Permalink to “步驟 4、測試和驗證 sftp”">​</a></h3><p>登錄到你的 <code>sftp</code> 服務器的同一個網絡上的任何其它的 Linux 系統，然後通過我們放入 <code>sftp_users</code> 組中的用户來嘗試 ssh 和 sftp 服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ssh root@linuxtechi</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>Write failed: Broken pipe</span></span>
<span class="line"><span>[root@linuxtechi ~]# ssh root@linuxtechi</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>Write failed: Broken pipe</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>以上操作證實用户不允許 <code>ssh</code> ，現在使用下面的命令嘗試 <code>sftp</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# sftp root@linuxtechi</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>Connected to 192.168.56.151.</span></span>
<span class="line"><span>sftp&gt; ls -l</span></span>
<span class="line"><span>drwxr-xr-x    2 root     1001         4096 Sep 14 07:52 debian10-pkgs</span></span>
<span class="line"><span>-rw-r--r--    1 root     1001          155 Sep 14 07:52 devops-actions.txt</span></span>
<span class="line"><span>drwxr-xr-x    2 1001     1002         4096 Sep 14 08:29 upload</span></span></code></pre></div><p>讓我們使用 sftp 的 <code>get</code> 命令來嘗試下載一個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sftp&gt; get devops-actions.txt</span></span>
<span class="line"><span>Fetching /devops-actions.txt to devops-actions.txt</span></span>
<span class="line"><span>/devops-actions.txt                                                                               100%  155     0.2KB/s   00:00</span></span>
<span class="line"><span>sftp&gt;</span></span>
<span class="line"><span>sftp&gt; cd /etc</span></span>
<span class="line"><span>Couldn&#39;t stat remote file: No such file or directory</span></span>
<span class="line"><span>sftp&gt; cd /root</span></span>
<span class="line"><span>Couldn&#39;t stat remote file: No such file or directory</span></span>
<span class="line"><span>sftp&gt;</span></span></code></pre></div><p>上面的輸出證實我們能從我們的 sftp 服務器下載文件到本地機器，除此之外，我們也必須測試用户不能更改目錄。</p><p>讓我們在 <code>upload</code> 目錄下嘗試上傳一個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sftp&gt; cd upload/</span></span>
<span class="line"><span>sftp&gt; put metricbeat-7.3.1-amd64.deb</span></span>
<span class="line"><span>Uploading metricbeat-7.3.1-amd64.deb to /upload/metricbeat-7.3.1-amd64.deb</span></span>
<span class="line"><span>metricbeat-7.3.1-amd64.deb                                                                        100%   38MB  38.4MB/s   00:01</span></span>
<span class="line"><span>sftp&gt; ls -l</span></span>
<span class="line"><span>-rw-r--r--    1 1001     1002     40275654 Sep 14 09:18 metricbeat-7.3.1-amd64.deb</span></span>
<span class="line"><span>sftp&gt;</span></span></code></pre></div><p>這證實我們已經成功地從我們的本地系統上傳一個文件到 sftp 服務中。</p><p>現在使用 winscp 工具來測試 sftp 服務，輸入 sftp 服務器 IP 地址和用户的憑證：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Winscp-sftp-debian10.jpg" alt=""></p><p>在 “Login” 上單擊，然後嘗試下載和上傳文件：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Download-file-winscp-debian10-sftp.jpg" alt=""></p><p>現在，在 <code>upload</code> 文件夾中嘗試上傳文件：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Upload-File-using-winscp-Debian10-sftp.jpg" alt=""></p><p>上面的窗口證實上傳是完好地工作的，這就是這篇文章的全部。如果這些步驟能幫助你在 Debian 10 中使用 chroot 環境配置 SFTP 服務器s，那麼請分享你的反饋和評論。</p><hr>`,53)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/configure-sftp-chroot-debian10/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/configure-sftp-chroot-debian10/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),n(e,{href:"https://github.com/robsean"},{default:t(()=>[...s[4]||(s[4]=[a("robsean",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=p(c,[["render",h]]);export{C as __pageData,y as default};
